#!/usr/bin/env node
// Package DF (2026-10-23, owner 01:57 notes 3 and 4): does difficulty climb, are levels doing their job.
//   node df_study.js census|econ|sims [games=40] [sweepGames=24]
// Reads the game's own fight build through tools/lib_bramble.js (referenceFightSetup / simulateReferenceFight), so the enemy levels,
// brambles, Shields, rules and CPU levels are what the game builds today. Writes to OUT (scratch) as JSON; df-2026-10-23.json is assembled from it.
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = process.env.DF_ROOT;
const OUT = process.env.DF_OUT;
const B = require(path.join(ROOT, 'tools/lib_bramble.js')), G = B.G, D = B.CARD_DEFS_BASELINE;
const cmd = process.argv[2];
const nums = process.argv.slice(3).filter(a=> /^\d+$/.test(a)).map(Number);
const GAMES = nums[0] || 40, SWEEP_GAMES = nums[1] || 24;
const r2 = v=> Math.round(v * 100) / 100, r1 = v=> Math.round(v * 10) / 10;
const ev = name=>{ const s = B.grab(name); return eval('(' + s.slice(s.indexOf('=') + 1).trim().replace(/;\s*$/, '') + ')'); };

const mains = G.CONQUEST_MAPS.filter(m=> !m.sub && !m.reserved && !m.tower && !m.endless);
const fightsOf = m=> m.nodes.filter(n=> n.deck && n.kind !== 'tutorial' && n.kind !== 'raidboss');
const ALL = []; mains.forEach(m=>{ const no = G.mapNumberOf(m.id); fightsOf(m).forEach((n, i)=> ALL.push({m, n, no, code: n.code || n.key, pos: i + 1, of: fightsOf(m).length})); });

// ---------------- decks
const ANT = {'tunnel-ant': 4, 'soldier-ant': 6, 'ant-scout': 6, 'worker-ant': 2, 'forager-ant': 2}; // every card Base (owned from the start, unlimited)
const FIRST_PACK = ev('SKIRMISH_FIRST_PACK_CARDS');
const firstCards = (mapId, key)=>{ const own = G.nodeRewardCardIds(mapId, key); const p = [].concat(FIRST_PACK[mapId + ':' + key] || []).filter(id=> D[id] && !own.includes(id)); return own.concat(p); };
const playable = d=> d && !d.token && !d.test && !d.hero && !d.hallOfFame && d.id !== 'wandering-traveller' && d.cardType !== 'materia' && d.cardType !== 'equipment' && (d.attack != null || d.health != null);
// what a player really holds arriving at map `no`: every Base card (unlimited), one copy of each first-clear card of the maps before it
function ownedAt(no){
  const own = {};
  Object.values(D).forEach(d=>{ if(playable(d) && G.cardSourceOf(d).kind === 'base') own[d.id] = 99; });
  mains.filter(m=> G.mapNumberOf(m.id) < no).forEach(m=> m.nodes.forEach(n=>{ if(n.kind === 'tutorial') return; firstCards(m.id, n.key).forEach(id=>{ if(playable(D[id])) own[id] = Math.min(99, (own[id] || 0) + 1); }); }));
  return own;
}
// the realistic progress deck: the 20 best by the game's own card score, at most 4 of a card and never more than owned
function progressDeck(no){
  const own = ownedAt(no), ids = Object.keys(own).sort((a, b)=> G.skirmishCardScore(D[b]) - G.skirmishCardScore(D[a]) || (a < b ? -1 : 1));
  const deck = {}; let n = 0;
  for(const id of ids){ const k = Math.min(4, own[id], G.maxCopiesForRarity(D[id].rarity), 20 - n); if(k <= 0) continue; deck[id] = k; n += k; if(n >= 20) break; }
  return deck;
}
const refDeck = no=>{ const built = Object.keys(G.WINRATE_REF_DECKS.road).map(Number).sort((a, b)=> a - b); const at = built.filter(k=> k <= no).pop(); return no <= 0 || !at ? G.WINRATE_REF_DECKS.starter : G.WINRATE_REF_DECKS.road[at]; };

// ---------------- economy (what a player can afford)
const SRC = B.src;
const REW = ev('CONQUEST_NODE_REWARDS'), MULT = ev('LEVEL_COST_MULT'), STEP = ev('FORGE_STEP_DUST'), TIERS = ev('FORGE_TIERS');
const KB = {champion: 'elite', miniboss: 'elite', subboss: 'boss', dungeon: 'elite', worldboss: 'raidboss', megaraid: 'raidboss'};
const firstDust = n=>{ const k = n.kind || 'skirmish'; if(k === 'tutorial') return {dust: 0, gold: 0}; const base = REW[k] || REW[KB[k]] || REW.skirmish, o = (n.rewards || {}).first || {};
  return {dust: o.dust != null && o.dust !== '' ? +o.dust : base.first.dust, gold: o.gold != null && o.gold !== '' ? +o.gold : base.first.gold}; };
const isBaseish = d=>{ const r = d.rarity || ''; const k = G.cardSourceOf(d).kind; return r === 'starter' || r === 'quest' || r === 'questunique' || d.basic || k === 'base' || k === 'map' || k === 'quest'; };
const tierOf = d=>{ const r = d.rarity || 'common'; return MULT[r] != null && r !== 'starter' ? r : 'common'; };
const multOf = d=> (MULT[tierOf(d)] || 1) * (d.hero ? 2 : isBaseish(d) ? 0.5 : 1);
const MOTE = {dust: Math.round(675 / 45), gold: Math.round(450 / 45)};
function stepCost(d, L){ if(L <= 0) return MOTE; const k = multOf(d), du = STEP[Math.min(9, L)]; return {dust: Math.round(du * k), gold: Math.round(du * 2 / 3 * k)}; }
function deckCostTo(deck, L){ let dust = 0, gold = 0; Object.entries(deck).forEach(([id, c])=>{ const d = D[id], from = G.cardBaseLevel(d); for(let l = from; l < L; l++){ const s = stepCost(d, l); dust += s.dust * c; gold += s.gold * c; } }); return {dust, gold}; }
const forgeCap = no=>{ if(no < 11) return 0; let cap = 0; TIERS.forEach(t=>{ if(!t.map || t.map <= no) cap = Math.max(cap, t.cap); }); return cap; };
const tierCostTo = no=> TIERS.filter(t=> t.map && t.map <= no).reduce((a, t)=> ({dust: a.dust + t.cost.dust, gold: a.gold + t.cost.gold}), {dust: 0, gold: 0});
// notices: 6 a day at the rank weights (QUEST_RANK_REWARD), + the three daily tiers, + the weekly tiers / 7; the Notices open on Map 4
const QW = ev('QUEST_RANK_WEIGHT'), QR = ev('QUEST_RANK_REWARD'), QT = ev('QUEST_TIERS');
const notice = {dust: 0, gold: 0}; Object.keys(QW).forEach(k=>{ notice.dust += QW[k] / 100 * QR[k].dust; notice.gold += QW[k] / 100 * QR[k].gold; });
const dailyTiers = QT.daily.reduce((a, t)=> ({dust: a.dust + (t.reward.dust || 0), gold: a.gold + (t.reward.gold || 0)}), {dust: 0, gold: 0});
const weeklyTiers = QT.weekly.reduce((a, t)=> ({dust: a.dust + (t.reward.dust || 0), gold: a.gold + (t.reward.gold || 0)}), {dust: 0, gold: 0});
const PACES = {
  typical: {about: 'a map a day; 6 notices a day from Map 4; 3/4 of the Dust goes to the main deck', mapsPerDay: 1, notices: 6, share: 0.75},
  light:   {about: 'a map a day; 3 notices a day; 3/4 to the deck', mapsPerDay: 1, notices: 3, share: 0.75},
  rush:    {about: 'three maps a day (a binge, like the owner\'s run); 6 notices a day; all Dust to the deck', mapsPerDay: 3, notices: 6, share: 1},
};
function econRows(pace){
  const rows = []; let fd = {dust: 0, gold: 0};
  for(let no = 0; no < mains.length; no++){
    const days = Math.max(0, no - 4) / pace.mapsPerDay; // notice-days since the Notices opened on Map 4
    const daily = {dust: pace.notices * notice.dust + dailyTiers.dust + weeklyTiers.dust / 7, gold: pace.notices * notice.gold + dailyTiers.gold + weeklyTiers.gold / 7};
    const earned = {dust: fd.dust + days * daily.dust, gold: fd.gold + days * daily.gold};
    const tc = tierCostTo(no), bank = {dust: Math.max(0, earned.dust * pace.share - tc.dust), gold: Math.max(0, earned.gold * pace.share - tc.gold)};
    const cap = forgeCap(no), nest = no >= 3 ? 1 : 0; // the Nest (Map 3) trains Lv 0 cards to Lv 1
    const lvFor = deck=>{ if(!cap) return {level: nest, cost: deckCostTo(deck, nest)}; let L = Math.max(1, nest); // whole levels, then the share of copies one more level up
      while(L < cap){ const c = deckCostTo(deck, L + 1); if(c.dust > bank.dust || c.gold > bank.gold) break; L++; }
      let frac = 0; if(L < cap){ const a = deckCostTo(deck, L), b = deckCostTo(deck, L + 1); frac = Math.max(0, Math.min(1, Math.min((bank.dust - a.dust) / Math.max(1, b.dust - a.dust), (bank.gold - a.gold) / Math.max(1, b.gold - a.gold)))); }
      return {level: r2(L + Math.floor(frac * 20) / 20), cost: deckCostTo(deck, L), costNext: L < cap ? deckCostTo(deck, L + 1) : null}; };
    const ant = lvFor(ANT), prog = lvFor(progressDeck(no)), ref = lvFor(refDeck(no));
    rows.push({map: no, days: r1(days), firstClearDust: Math.round(fd.dust), earnedDust: Math.round(earned.dust), earnedGold: Math.round(earned.gold), forgeTierDust: tc.dust, bankDust: Math.round(bank.dust), forgeCap: cap,
      antLevel: ant.level, antCostToCap: cap ? deckCostTo(ANT, cap).dust : 0, progLevel: prog.level, progCostToCap: cap ? deckCostTo(progressDeck(no), cap).dust : 0, refLevel: ref.level, refCostToCap: cap ? deckCostTo(refDeck(no), cap).dust : 0});
    mains[no].nodes.forEach(n=>{ const x = firstDust(n); fd.dust += x.dust; fd.gold += x.gold; });
    G.CONQUEST_MAPS.filter(s=> s.sub && s.parent === mains[no].id && !s.reserved && !s.tower).forEach(s=> s.nodes.forEach(n=>{ const x = firstDust(n); fd.dust += x.dust; fd.gold += x.gold; }));
  }
  return rows;
}
// duplicates: how hard one more copy of a given card is
function dupModel(){
  const W = ev('PACK_RARITY_WEIGHT');
  const pool1 = Object.values(D).filter(d=> G.cardSourceOf(d).kind === 'pack' && (d.source || {}).tier === 1);
  const tot = pool1.reduce((a, d)=> a + (W[d.rarity] || 0), 0);
  const pSpecific = r=> (W[r] || 0) / tot;
  const SHARE = {common: 0.6, uncommon: 0.5, rare: 0.4}; // RW2-1's rarity share on a repeat drop of a first-clear card
  const out = {pool1Cards: pool1.length, pool1Weight: r1(tot), perPackCard: {}, perRepeatSkirmish: {}, hedgerowPouchesForOneMore: {}, repeatFightsForOneMore: {}};
  ['common', 'uncommon', 'rare', 'epic'].forEach(r=>{ const p = pSpecific(r); out.perPackCard[r] = +p.toFixed(5); out.hedgerowPouchesForOneMore[r] = Math.round(1 / (3 * p));
    const s = SHARE[r] || 0.3; out.perRepeatSkirmish[r] = +(0.03 * s).toFixed(4); out.repeatFightsForOneMore[r] = Math.round(1 / (0.03 * s)); });
  out.notes = 'Packs are fully random since RW3 (no map gate): one specific common is 1 in ~' + Math.round(1 / pSpecific('common')) + ' pack cards. A repeat of the skirmish that pays it on first clear drops it 3% x its rarity share a fight (1 Energy). A Hedgerow Pouch is 3 cards for 50 gold.';
  return out;
}

// ---------------- census
function census(){
  const rows = ALL.map(({m, n, no, code, pos, of})=>{
    const ctx = G.referenceFightSetup(m.id, n, {});
    let copies = 0, A = 0, H = 0, w = 0, ah = 0; const rar = {}, skills = {}, arch = {}, lvs = {};
    Object.entries(ctx.enemyDeck).forEach(([id, k])=>{ const d = ctx.defs[id] || {}, b = D[d.derivedFrom || id.replace(/@lv\d+$/, '')] || d; copies += k; A += k * (d.attack || 0); H += k * (d.health || 0); w += k * (2 * (d.attack || 0) + (d.health || 0)); ah += k * ((d.attack || 0) + 1) * Math.max(1, d.health || 0);
      const r = b.rarity || 'common'; rar[r] = (rar[r] || 0) + k; Object.keys(b.effects || {}).forEach(s=>{ if(s !== 'triggers') skills[s] = (skills[s] || 0) + k; });
      (b.archetypes || []).forEach(a=>{ arch[a] = (arch[a] || 0) + k; }); const lv = /@lv(\d+)$/.exec(id); const L = lv ? +lv[1] : G.cardBaseLevel(b); lvs[L] = (lvs[L] || 0) + k; });
    const rules = ctx.rules || {}, fx = Object.keys(rules).filter(k=> !['phaseDay', 'phaseNight', 'ashyAfterEruption'].includes(k) && rules[k] && !(k === 'phase' && rules[k] === 'off') && !(k === 'eruption' && !rules[k]))
      .map(k=> k === 'terrain' ? 'terrain:' + rules.terrain.biome + ' ' + rules.terrain.tier : k === 'phase' ? 'phase:' + rules.phase : (typeof rules[k] === 'object' ? k : k + (rules[k] === true ? '' : ':' + rules[k])));
    if(m.id === 'm6') fx.push('field:frozen');
    const top = o=> Object.entries(o).sort((a, b)=> b[1] - a[1]).slice(0, 4).map(([k, v])=> k + ' ' + v);
    return {map: no, mapId: m.id, mapName: m.name, code, key: n.key, kind: n.kind || 'skirmish', name: n.name || n.key, pos, of, enemyLevel: r2(G.roadEnemyLevelExact(n)), levelCopies: lvs, cpu: ctx.cpu,
      deckSize: copies, meanA: r2(A / copies), meanH: r2(H / copies), mean2AH: r2(w / copies), meanAH: r2(ah / copies), rarity: rar, topSkills: top(skills), topArchetypes: top(arch),
      leaders: G.skirmishLeadersOf(n, m.id), brambleHp: ctx.sc.hp, shield: ctx.sc.shield, brambleTotal: ctx.sc.hp + ctx.sc.shield, myBramble: ctx.myCastle.health, fields: fx,
      refLevel: G.referencePlayerLevel(no)};
  });
  return rows;
}

// ---------------- sims
function sims(){
  const econ = econRows(PACES.typical), lvAt = no=> econ[no];
  const outF = path.join(OUT, 'df-sims.jsonl'); const done = new Set(); try{ fs.readFileSync(outF, 'utf8').split('\n').filter(Boolean).forEach(l=> done.add(JSON.parse(l).key)); }catch(e){}
  const t0 = Date.now(); let i = 0;
  for(const {m, n, no, code} of ALL){ i++; const key = m.id + ':' + n.key; if(done.has(key)) continue; const t = Date.now();
    const e = lvAt(no), run = (deck, level, games)=>{ const r = G.simulateReferenceFight(m.id, n, games, {deck, level}); return {win: r1(r.win * 100), hpLost: r1(r.hpLost * 100), rounds: r.avgRounds ? r1(r.avgRounds) : null, level}; };
    const pd = progressDeck(no), rd = refDeck(no);
    const res = {
      ant: run(ANT, e.antLevel, GAMES), prog: run(pd, e.progLevel, GAMES), ref: run(rd, e.refLevel, GAMES),
      antL1: run(ANT, 1, SWEEP_GAMES), antL4: run(ANT, 4, SWEEP_GAMES), antL8: run(ANT, 8, SWEEP_GAMES),
    };
    fs.appendFileSync(outF, JSON.stringify({key, map: no, code, kind: n.kind || 'skirmish', enemyLevel: r2(G.roadEnemyLevelExact(n)), res, progDeck: pd, ms: Date.now() - t}) + '\n');
    if(i % 10 === 0) console.log(i, '/', ALL.length, Math.round((Date.now() - t0) / 1000) + 's');
  }
}

// ---------------- trial enemy curves (node.enemyLevel on a trial copy; nothing written to the game)
const CURVES = {
  pace: {about: 'the enemy keeps 0.5-2.5 levels under the Forge cap: Map 11-12 Lv 3, 13 3.5, 14 4, 15 4.5, 16 5.5, then +0.25 a map (7.75 at Map 24); elites +0.5, bosses and world bosses +1',
    at: no=> no <= 10 ? null : no <= 12 ? 3 : no === 13 ? 3.5 : no === 14 ? 4 : no === 15 ? 4.5 : 5.5 + (no - 16) * 0.25},
  half: {about: 'halfway between today\'s schedule and pace', at: no=> null},
};
function trial(){
  const econ = econRows(PACES.typical), outF = path.join(OUT, 'df-trial.jsonl'); const done = new Set(); try{ fs.readFileSync(outF, 'utf8').split('\n').filter(Boolean).forEach(l=> done.add(JSON.parse(l).key)); }catch(e){}
  for(const {m, n, no, code} of ALL){ if(no < 11) continue; const key = m.id + ':' + n.key; if(done.has(key)) continue;
    const today = G.roadEnemyLevelExact(n), k = n.kind || 'skirmish', bump = /boss/.test(k) ? 1 : k === 'skirmish' ? 0 : 0.5;
    const pace = CURVES.pace.at(no) + bump, half = r2((today + pace) / 2), e = econ[no], pd = progressDeck(no), out = {key, map: no, code, kind: k, today: r2(today), pace, half, res: {}};
    for(const [lab, L] of [['pace', pace], ['half', half]]){ const t = Object.assign({}, n, {enemyLevel: L}); G.NODE_MAP_HINT.set(t, m.id);
      const run = (deck, level)=>{ const r = G.simulateReferenceFight(m.id, t, GAMES, {deck, level}); return r1(r.win * 100); };
      out.res[lab] = {ant: run(ANT, e.antLevel), prog: run(pd, e.progLevel)}; }
    fs.appendFileSync(outF, JSON.stringify(out) + '\n'); }
}

if(cmd === 'trial') trial();
else if(cmd === 'census'){ fs.writeFileSync(path.join(OUT, 'df-census.json'), JSON.stringify(census(), null, 0)); console.log('census', ALL.length); }
else if(cmd === 'econ'){ const o = {paces: PACES, notice: {dust: r1(notice.dust), gold: r1(notice.gold)}, dailyTiers, weeklyTiers, rows: Object.fromEntries(Object.entries(PACES).map(([k, p])=> [k, econRows(p)])), dup: dupModel(),
  decks: {ant: ANT, progress: Object.fromEntries([1, 3, 5, 8, 11, 14, 17, 20, 24].map(no=> [no, progressDeck(no)])), ref: 'WINRATE_REF_DECKS.road (arena_app.js)'},
  costs: {antTo: Object.fromEntries([1, 2, 3, 4, 5, 6, 7, 8].map(L=> [L, deckCostTo(ANT, L)])), refMap20To: Object.fromEntries([1, 3, 4, 8].map(L=> [L, deckCostTo(refDeck(20), L)]))}};
  fs.writeFileSync(path.join(OUT, 'df-econ.json'), JSON.stringify(o, null, 1)); console.log(JSON.stringify(o.rows.typical.map(r=> [r.map, r.bankDust, r.forgeCap, r.antLevel, r.progLevel, r.refLevel]))); console.log(JSON.stringify(o.dup)); console.log(JSON.stringify(o.costs)); }
else if(cmd === 'sims') sims();

scripts.share:
const B=require(process.env.DF_ROOT+"/tools/lib_bramble.js"),G=B.G,D=B.CARD_DEFS_BASELINE;
const P={5:["arch","Snake"],6:["arch","Swamp"],7:["arch","Insect|Flora"],8:["arch","Cave"],9:["arch","Mangrove"],10:["skill","tide"],11:["skill","flying"],12:["skill","thorns"],13:["arch","Fox"],14:["arch","Savanna"],15:["arch","Horse"],16:["arch","Wolf"],17:["arch","Frost|Tundra"],18:["arch","Desert"],19:["arch","Volcanic|Porcupine"],20:["arch","Volcanic"],21:["skill","guardian"],22:["arch","Volcanic|Frost"],23:["skill","siege"],24:["arch","Duck"]};
const mains=G.CONQUEST_MAPS.filter(m=>!m.sub&&!m.reserved&&!m.tower&&!m.endless);const out={};
mains.forEach(m=>{const no=G.mapNumberOf(m.id);if(!P[no])return;const [k,v]=P[no],re=new RegExp("^("+v+")$");let met=0,tot=0;const sh=[];
m.nodes.filter(n=>n.deck&&n.kind!=="tutorial"&&n.kind!=="raidboss").forEach(n=>{let c=0,t=0;Object.entries(n.deck).forEach(([id,q])=>{const d=D[id];if(!d)return;t+=q;const ok=k=="arch"?(d.archetypes||[]).some(a=>re.test(a)):Object.keys(d.effects||{}).some(s=>re.test(s));if(ok)c+=q});tot++;const s=c/t;sh.push(Math.round(s*100));if(s>=0.5)met++});
out[no]={theme:v,by:k,met,of:tot,shares:sh};console.log(no,v,met+"/"+tot,sh.join(" "))});
require("fs").writeFileSync(process.env.DF_OUT+"/df-share.json",JSON.stringify(out));
